-- Rollback of daily-bank-2026-12-lot3.sql: removes the rows of this lot that were not
-- published yet (a published row is already a live quiz page; it stays). Kpop rows only.
delete from public.quiz_bank qb
where title in ('ITZY: From Debut to Born to Be', 'K-pop Idol MCs Through the Years', 'EXO: The XOXO Era', 'K-pop Songs With a Flower in the Title', 'GOT7 True or False', 'MAMAMOO: From Mr. Ambiguous to Starry Night', 'SHINee: The Odd Era of 2015', 'K-pop Songs of 2015', 'K-pop Songs on the Phone', 'STAYC: From So Bad to Cheeky Icy Thang', 'Apink True or False', 'NCT 127: The Sticker Era', 'Korea''s Year-End Chart Toppers', 'NCT DREAM: From Chewing Gum to Smoothie', 'K-pop Songs With Foreign Titles', '2NE1: The Crush Era', 'K-pop and Korean Tradition True or False', 'P1Harmony: From Siren to Sad Song', 'Who Directed These K-pop Music Videos?', 'K-pop Song Titles That Ask a Question') and status in ('verified', 'scheduled') and published_quiz_id is null and coalesce(to_jsonb(qb) ->> 'site_id', 'kpop') = 'kpop';
